import { test, expect } from '@playwright/test';

test.describe('Permissions Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
    await page.fill('input[name="username"]', 'user1');
    await page.fill('input[name="password"]', 'password1');
    await page.click('button[type="submit"]');
    await page.waitForNavigation();
  });

  test('should display permissions error when trying to edit another user\'s content', async ({ page }) => {
    await page.goto('/content/user2');
    await page.click(getByRole('button', { name: /edit/i }));
    await expect(page.getByText(/you do not have permission to edit this content/i)).toBeVisible();
  });

  test('should not display permissions error when editing own content', async ({ page }) => {
    await page.goto('/content/user1');
    await page.click(getByRole('button', { name: /edit/i }));
    await expect(page.getByText(/edit your content/i)).toBeVisible();
  });
});
